import json

print("=== ASV Empirical Results ===")
with open('plan006/asv_empirical_results.json') as f:
    data = json.load(f)

    # Extract from biases section
    if 'biases' in data:
        biases = data['biases']
        for topo, vals in biases.items():
            if isinstance(vals, dict):
                print(f"\n{topo}:")
                for k in ['IV_bias_range', 'exposure_bias_range', 'bias_range', 'min', 'max']:
                    if k in vals:
                        print(f"  {k}: {vals[k]}")

    # Extract from f1_vs_bias
    if 'f1_vs_bias' in data:
        f1b = data['f1_vs_bias']
        print(f"\nF1-Bias Correlation:")
        for k in ['spearman_rho', 'rho', 'p_value', 'n_configs']:
            if k in f1b:
                print(f"  {k}: {f1b[k]}")

        # Per-topology
        if 'per_topology' in f1b:
            print(f"\n  Per-topology rho:")
            for topo, val in f1b['per_topology'].items():
                if isinstance(val, dict):
                    print(f"    {topo}: {val.get('rho', val.get('spearman_rho', 'N/A'))}")

    # Type 1/2
    if 'type1_type2' in data:
        t12 = data['type1_type2']
        print(f"\nType 1/2 (Sign Flips):")
        for k, v in t12.items():
            if isinstance(v, (int, float)):
                print(f"  {k}: {v}")
